            rows: [
              ['Seeking employment (ethics regulation)', 'Everyone', 'Participating in matters affecting a company you are seeking employment with', 'While seeking; ends on rejection'],
              ['Procurement Integrity Act, reporting', 'Anyone participating in a procurement above threshold', 'Must report employment contacts from bidders and reject or disqualify', 'During the procurement'],
              ['Procurement Integrity Act, compensation ban', 'COs, PMs, source selection roles, and certain approvers on contracts above threshold', 'Accepting compensation from that contractor', 'One year from the specified action'],
              ['207 lifetime ban', 'Officers and civilians', 'Representing others to the government on particular matters you personally and substantially worked', 'Forever'],
              ['207 two-year ban', 'Officers and civilians', 'Representing others on matters under your official responsibility in your last year', 'Two years'],
              ['207 one-year cooling-off', 'Senior officials (O-7+, SES, and equivalents)', 'Communicating with your former agency on behalf of anyone, on anything', 'One year'],
              ['DoD ethics opinion letter', 'Senior officials and acquisition officials on contracts above threshold', 'Must obtain a written ethics opinion before accepting defense contractor compensation', 'Two years after leaving'],
            ],
